export const theme = {
  colors: {
    primary: '#1ABC9C',        // Vibrant Teal (primary CTAs)
    primaryDark: '#169f86',
    secondary: '#2C3E50',      // Charcoal Blue (headers/nav/sidebar)
    accent: '#1ABC9C',         // Use same teal for accents/active indicators
    success: '#1ABC9C',        // Align success with accent for cohesive CTAs
    warning: '#F39C12',
    error: '#E74C3C',
    background: '#F0F2F5',     // Light Gray (main backgrounds)
    surface: '#ffffff',
    surfaceVariant: '#EEF1F4',
    text: '#212121',           // Dark Gray (primary text)
    textSecondary: '#95A5A6',  // Medium Gray (secondary/subtle text)
    textLight: '#B0BEC5',
    border: '#E0E6EA',
    borderLight: '#F3F6F8',
    white: '#ffffff',
    black: '#000000',
  },
  spacing: {
    xs: 4,
    sm: 8,
    md: 16,
    lg: 24,
    xl: 32,
    xxl: 48,
    xxxl: 64,
  },
  borderRadius: {
    sm: 6,
    md: 10,
    lg: 14,
    xl: 18,
    full: 9999,
  },
  fontSize: {
    xs: 12,
    sm: 14,
    md: 16,
    lg: 18,
    xl: 20,
    xxl: 24,
    xxxl: 32,
  },
  fontWeight: {
    normal: '400' as const,
    medium: '500' as const,
    semibold: '600' as const,
    bold: '700' as const,
  },
  shadows: {
    sm: {
      shadowColor: '#000',
      shadowOffset: {
        width: 0,
        height: 1,
      },
      shadowOpacity: 0.05,
      shadowRadius: 2,
      elevation: 1,
    },
    md: {
      shadowColor: '#000',
      shadowOffset: {
        width: 0,
        height: 2,
      },
      shadowOpacity: 0.08,
      shadowRadius: 6,
      elevation: 3,
    },
    lg: {
      shadowColor: '#000',
      shadowOffset: {
        width: 0,
        height: 6,
      },
      shadowOpacity: 0.12,
      shadowRadius: 12,
      elevation: 6,
    },
  },
  layout: {
    containerMaxWidth: 1200,
    breakpoints: {
      sm: 480,
      md: 768,
      lg: 1024,
      xl: 1280,
    },
  },
};

export type Theme = typeof theme;
